// app/livres/page.js
export default async function PageLivres() {
  const livres = await obtenirLivres();
  return <ListeLivres livres={livres} />;
}

"use client";

import { useState } from "react";

export function Filtre() {
  const [texte, setTexte] = useState("");
  return <input value={texte} onChange={(e) => setTexte(e.target.value)} />;
}
